const coreFeatures: FeatureSeed[] = [
  { level: 1, name: 'Martial Arts', description: 'While unarmed or wielding only Monk weapons—simple melee weapons and martial melee weapons with the Light property—and wearing no armor or Shield, you gain three benefits. Make one Unarmed Strike as a bonus action. Use the Martial Arts die shown in the Monk table for an Unarmed Strike or Monk weapon. Use Dexterity instead of Strength for attack and damage rolls and for the save DC of Grapple or Shove made through an Unarmed Strike.' },
  { level: 1, name: 'Unarmored Defense', description: 'While wearing no armor and wielding no Shield, your base Armor Class equals 10 + your Dexterity modifier + your Wisdom modifier.' },
  { level: 2, name: "Monk's Focus", description: 'You have Focus Points equal to your Monk level, restored after a short or long rest. Focus save DC = 8 + Wisdom modifier + proficiency bonus. Flurry of Blows spends 1 Focus Point to make two Unarmed Strikes as a bonus action. Patient Defense lets you Disengage as a bonus action, or spend 1 point to Disengage and Dodge together. Step of the Wind lets you Dash as a bonus action, or spend 1 point to Disengage and Dash together and double jump distance for the turn.' },
  { level: 2, name: 'Unarmored Movement', description: 'While wearing no armor and wielding no Shield, increase your speed by the amount shown in the Monk progression table: +10 feet at level 2, +15 at level 6, +20 at level 10, +25 at level 14, and +30 at level 18.' },
  { level: 2, name: 'Uncanny Metabolism', description: 'Once per long rest when you roll initiative, regain all expended Focus Points and regain hit points equal to your Monk level + one roll of your Martial Arts die.' },
  { level: 3, name: 'Deflect Attacks', description: 'When an attack hits you and includes bludgeoning, piercing, or slashing damage, use your reaction to reduce its total damage by 1d10 + Dexterity modifier + Monk level. If reduced to 0, spend 1 Focus Point to redirect the force. Choose a visible creature within 5 feet for a melee attack or within 60 feet and not behind total cover for a ranged attack. It makes a Dexterity save, taking two Martial Arts dice + Dexterity modifier of the triggering damage type on failure.' },
  { level: 3, name: 'Monk Subclass', description: 'Choose a Monk subclass. It grants features at Monk levels 3, 6, 11, and 17. Every Monk subclass in the archive is available under both the 2014 and 2024 rulesets.' },
  { level: 4, name: 'Ability Score Improvement', description: 'Gain the Ability Score Improvement feat or another feat for which you qualify. You gain this feature again at Monk levels 8, 12, and 16.' },
  { level: 4, name: 'Slow Fall', description: 'When you fall, use your reaction to reduce the falling damage you take by five times your Monk level.' },
  { level: 5, name: 'Extra Attack', description: 'Attack twice instead of once whenever you take the Attack action on your turn.' },
  { level: 5, name: 'Stunning Strike', description: 'Once per turn when you hit with a Monk weapon or Unarmed Strike, spend 1 Focus Point. The target makes a Constitution save. On failure, it is stunned until your next turn starts. On success, its speed is halved until then, and the next attack against it before then has advantage.' },
  { level: 6, name: 'Empowered Strikes', description: 'Whenever your Unarmed Strike deals damage, choose for it to deal force damage or its normal damage type.' },
  { level: 7, name: 'Evasion', description: 'When an effect permits a Dexterity save for half damage, take no damage on a success and half on a failure. You gain no benefit while incapacitated.' },
  { level: 8, name: 'Ability Score Improvement (8th Level)', description: 'Gain the Ability Score Improvement feat or another feat for which you qualify.' },
  { level: 9, name: 'Acrobatic Movement', description: 'While wearing no armor and wielding no Shield, move along vertical surfaces and across liquids during your turn without falling during the movement.' },
  { level: 10, name: 'Heightened Focus', description: 'Flurry of Blows makes three Unarmed Strikes instead of two. Spending Focus on Patient Defense also grants temporary hit points equal to two Martial Arts dice. Spending Focus on Step of the Wind lets you carry one willing Large or smaller creature within 5 feet along with your movement without provoking opportunity attacks.' },
  { level: 10, name: 'Self-Restoration', description: 'At the end of each of your turns, end the charmed, frightened, or poisoned condition on yourself. Forgoing food and drink does not give you Exhaustion.' },
  { level: 12, name: 'Ability Score Improvement (12th Level)', description: 'Gain the Ability Score Improvement feat or another feat for which you qualify.' },
  { level: 13, name: 'Deflect Energy', description: 'Deflect Attacks can now reduce an attack that deals any damage type, rather than only bludgeoning, piercing, or slashing damage.' },
  { level: 14, name: 'Disciplined Survivor', description: 'Gain proficiency in every saving throw. Whenever you fail a saving throw, spend 1 Focus Point to reroll it and use the new result.' },
  { level: 15, name: 'Perfect Focus', description: 'When you roll initiative and do not use Uncanny Metabolism, regain expended Focus Points until you have 4 if you currently have 3 or fewer.' },
  { level: 16, name: 'Ability Score Improvement (16th Level)', description: 'Gain the Ability Score Improvement feat or another feat for which you qualify.' },
  { level: 18, name: 'Superior Defense', description: 'At the start of your turn, spend 3 Focus Points to gain resistance to all damage except force damage for 1 minute or until you become incapacitated.' },
  { level: 19, name: 'Epic Boon', description: 'Gain an Epic Boon feat or another feat for which you qualify. Boon of Irresistible Offense is recommended.' },
  { level: 20, name: 'Body and Mind', description: 'Increase your Dexterity and Wisdom scores by 4, to a maximum of 25.' },
]

