const ASCENDANT_DRAGON_UA_ID = 'subclass-ascendant-dragon-ua'
const ASCENDANT_DRAGON_UA_FEATURES: Record<string, FeatureSeed> = {
  'feature-subclass-ascendant-dragon-ua-3-draconic-disciple': { level: 3, name: 'Draconic Disciple', description: 'Gain three draconic benefits. When an Unarmed Strike damages a target, change its damage type to acid, cold, fire, lightning, or poison. Learn to speak, read, and write Draconic if you cannot already. After failing an Intimidation or Persuasion check, use your reaction to reroll it; once this reroll turns failure into success, regain it after a long rest.' },
  'feature-subclass-ascendant-dragon-ua-3-breath-of-the-dragon': { level: 3, name: 'Breath of the Dragon', description: 'When taking the Attack action, replace one attack with draconic energy in a 20-foot cone or a 30-foot-long, 5-foot-wide line. Choose acid, cold, fire, lightning, or poison damage. Each creature in the area makes a Dexterity save against your Focus (Ki) save DC, taking two Martial Arts dice on failure or half on success; this becomes three Martial Arts dice at level 11. Use this feature a number of times equal to your proficiency bonus per long rest. With no uses remaining, spend 1 Focus Point (Ki Point) to use it again.' },
  'feature-subclass-ascendant-dragon-ua-6-wings-unfurled': { level: 6, name: 'Wings Unfurled', description: 'When using Step of the Wind, unfurl spectral draconic wings until your turn ends and gain a flying speed equal to your walking speed. Use this feature a number of times equal to your proficiency bonus per long rest. With no uses remaining, spend 1 additional Focus Point (Ki Point) when activating Step of the Wind to use it again.' },
  'feature-subclass-ascendant-dragon-ua-11-aspect-of-the-wyrm': { level: 11, name: 'Aspect of the Wyrm', description: 'As a bonus action, create a 30-foot aura for 1 minute and choose acid, cold, fire, lightning, or poison damage. You and allies within the aura have resistance to the chosen type. When you or an ally in the aura is hit by an attack made by another creature within the aura, the hit target may use its reaction to deal one Martial Arts die of the chosen damage to the attacker. Once used, regain the aura after a long rest, or spend 4 Focus Points (Ki Points) to use it again.' },
  'feature-subclass-ascendant-dragon-ua-17-ascendant-aspect': { level: 17, name: 'Ascendant Aspect', description: 'Gain blindsight to 30 feet, perceiving anything not behind total cover, including invisible creatures that are not hidden. When Breath of the Dragon damages a creature, it takes one Martial Arts die of the breath’s damage type at the start of each turn, then repeats the save at the end of that turn to end the effect. When activating Aspect of the Wyrm, choose visible creatures in the aura; each takes 4d10 acid, cold, fire, lightning, or poison damage, chosen by you.' },
}
const ASTRAL_SELF_UA_ID = 'subclass-astral-self-ua'
const ASTRAL_SELF_UA_FEATURES: Record<string, FeatureSeed> = {
  'feature-subclass-astral-self-ua-3-arms-of-the-astral-self': { level: 3, name: 'Arms of the Astral Self', description: 'As a bonus action, spend 2 Focus Points (Ki Points) to summon spectral arms for 10 minutes. While present, use Wisdom instead of Strength for Strength checks and saving throws. The arms are Monk weapons with 10-foot reach, deal radiant or necrotic damage chosen by you, and can use Wisdom instead of Strength or Dexterity for attack and damage rolls. Immediately after taking the Attack action with the arms, make one arm attack as a bonus action; this becomes two bonus attacks at level 11 and three at level 17.' },
  'feature-subclass-astral-self-ua-6-visage-of-the-astral-self': { level: 6, name: 'Visage of the Astral Self', description: 'As a bonus action, or as part of summoning the astral arms, spend 1 Focus Point (Ki Point) to summon a spectral visage for 10 minutes. Wisdom of the Spirit grants advantage on Insight and Intimidation checks. Astral Sight lets you see normally through magical and nonmagical darkness to 120 feet.' },
  'feature-subclass-astral-self-ua-11-awakening-of-the-astral-self': { level: 11, name: 'Awakening of the Astral Self', description: 'While both astral arms and visage are summoned, gain three benefits. Deflect Energy: when taking acid, cold, fire, lightning, or force damage, use your reaction to reduce it by 1d10 + your Wisdom modifier + your Monk level. Empowered Arms: once on each of your turns when the arms hit, deal one extra Martial Arts die. Word of the Spirit: speak privately to one visible creature within 30 feet, or amplify your voice to all creatures within 600 feet.' },
  'feature-subclass-astral-self-ua-17-complete-astral-self': { level: 17, name: 'Complete Astral Self', description: 'As a bonus action, spend 10 Focus Points (Ki Points) to summon the complete astral self for 10 minutes. Armor of the Spirit grants +2 AC while you are not incapacitated. Astral Barrage lets Extra Attack make three astral-arm attacks instead of two. Ki Consumption: when a creature within 10 feet is reduced to 0 Hit Points, use your reaction to regain Focus Points (Ki Points) equal to your Wisdom modifier, with a minimum of 1.' },
}
const KENSEI_UA_ID = 'subclass-kensei-ua'
const KENSEI_UA_FEATURES: Record<string, FeatureSeed> = {
  'feature-subclass-kensei-ua-3-path-of-the-kensei': { level: 3, name: 'Path of the Kensei', description: 'Gain proficiency with three martial weapons of your choice; every martial weapon with which you are proficient is a Kensei weapon for you. When wielding a Kensei weapon, choose Strength or Dexterity for its attack and damage rolls and choose whether to replace its damage die with your Martial Arts die. After taking the Attack action and hitting with a Kensei weapon, use a bonus action to pummel: the hit target and every other target you hit with that weapon as part of the Attack each take an extra 1d4 bludgeoning damage. After making an Unarmed Strike as part of the Attack action while holding a Kensei weapon, gain +2 AC until your next turn starts while holding it and not incapacitated.' },
  'feature-subclass-kensei-ua-6-one-with-the-blade': { level: 6, name: 'One with the Blade', description: 'Gain two benefits. Magic Weapons: attacks with Kensei weapons count as magical for overcoming resistance and immunity to nonmagical attacks and damage. Precise Strike: as a bonus action, choose one visible creature within 30 feet; your next weapon attack against it during the current turn adds twice your proficiency bonus to the attack roll instead of the normal bonus. Once used, regain Precise Strike after a short or long rest.' },
  'feature-subclass-kensei-ua-11-sharpen-the-blade': { level: 11, name: 'Sharpen the Blade', description: 'As a bonus action, spend up to 3 Focus Points (Ki Points) and touch a weapon. While you wield it, that weapon gains a bonus to attack and damage rolls equal to the points spent. The bonus lasts for 1 minute.' },
  'feature-subclass-kensei-ua-17-unerring-accuracy': { level: 17, name: 'Unerring Accuracy', description: 'Once on each of your turns, reroll one weapon attack roll you make that misses.' },
}
