  'feature-subclass-way-of-mercy-ua-3-hands-of-healing': { level: 3, name: 'Hands of Healing', description: 'As an action, spend 1 Focus Point (Ki Point) to touch a creature and restore Hit Points equal to one roll of your Martial Arts die + your Wisdom modifier. When using Flurry of Blows, replace one Unarmed Strike with this healing without spending its point cost.' },
  'feature-subclass-way-of-mercy-ua-3-hands-of-harm': { level: 3, name: 'Hands of Harm', description: 'Once on each of your turns when an Unarmed Strike hits a creature, spend 1 Focus Point (Ki Point) to deal extra necrotic damage equal to one Martial Arts die. If the creature is incapacitated or poisoned, the extra damage instead equals three Martial Arts dice.' },
  'feature-subclass-way-of-mercy-ua-6-noxious-aura': { level: 6, name: 'Noxious Aura', description: 'As a bonus action, spend 1 Focus Point (Ki Point) to create a toxic aura extending 5 feet from you but not through total cover. It lasts 1 minute, until you are incapacitated, or until you dismiss it without an action. Ranged attacks against you have disadvantage. Any other creature starting its turn in the aura makes a Constitution save or becomes poisoned until your next turn ends and takes poison damage equal to your Wisdom modifier, with a minimum of 0.' },
