const TRANQUILITY_FEATURES: Record<string, FeatureSeed> = {
  'feature-subclass-tranquility-3-path-of-tranquility': { level: 3, name: 'Path of Tranquility', description: 'Cast Sanctuary on yourself without material components; it lasts up to 8 hours and has a saving throw DC of 8 + your proficiency bonus + your Wisdom modifier. A creature that succeeds on the save is immune to this use for 1 hour. Once cast this way, you cannot cast it this way again for 1 minute.' },
  'feature-subclass-tranquility-3-healing-hands': { level: 3, name: 'Healing Hands', description: 'Gain a healing pool equal to ten times your Monk level that replenishes after a long rest. As an action, touch a creature and spend any remaining points to restore that many Hit Points. Instead, spend 5 pool points per disease cured or poison neutralized, resolving multiple effects in one use by paying separately. When using Flurry of Blows, replace one Unarmed Strike with Healing Hands. This feature has no effect on Undead or Constructs.' },
  'feature-subclass-tranquility-6-emissary-of-peace': { level: 6, name: 'Emissary of Peace', description: 'Gain advantage on Charisma checks made in good faith to calm violent emotions or counsel peace; this does not apply when Deception or Intimidation proficiency would apply. Also gain proficiency in either Performance or Persuasion, chosen by you.' },
  'feature-subclass-tranquility-11-douse-the-flames-of-war': { level: 11, name: 'Douse the Flames of War', description: 'As an action, touch a creature and force a Wisdom saving throw against DC 8 + your proficiency bonus + your Wisdom modifier; a creature missing any Hit Points automatically succeeds. On failure, for 1 minute it cannot attack or cast spells that deal damage or force a saving throw. The effect ends if it is attacked, damaged, or forced to save, or if it witnesses any of those events affecting one of its allies.' },
  'feature-subclass-tranquility-17-anger-of-a-gentle-soul': { level: 17, name: 'Anger of a Gentle Soul', description: 'When you see a creature reduce another creature to 0 Hit Points, use your reaction to gain a bonus equal to your Monk level on every damage roll you make against the aggressor until your next turn ends. Once used, regain this feature after a short or long rest.' },
}
